### App.jsx - React Flow with default controls

Source: https://reactflow.dev/llms-medium.txt

Main React Flow component with default viewport controls. Uses useNodesState and useEdgesState to manage nodes and edges, and addEdge to handle new connections. Includes a Background and fitView.

```jsx
import { useCallback } from 'react';
import {
  Background,
  ReactFlow,
  addEdge,
  useEdgesState,
  useNodesState,
} from '@xyflow/react';
import '@xyflow/react/dist/style.css';

import { initialNodes } from './nodes';
import { initialEdges } from './edges';

function Flow() {
  const [nodes, setNodes, onNodesChange] = useNodesState(initialNodes);
  const [edges, setEdges, onEdgesChange] = useEdgesState(initialEdges);

  const onConnect = useCallback(
    (connection) => setEdges((eds) => addEdge(connection, eds)),
    [setEdges],
  );

  return (
    <ReactFlow
      nodes={nodes}
      edges={edges}
      onNodesChange={onNodesChange}
      onEdgesChange={onEdgesChange}
      onConnect={onConnect}
      fitView
      colorMode="system"
    >
      <Background/>
    </ReactFlow>
  );
}

export default Flow;
```

