import { chromium } from "playwright";
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1600, height: 1000 }, colorScheme: "dark" });
const errs = [];
p.on("console", (m) => m.type() === "error" && !m.text().includes("unpkg") && errs.push(m.text().slice(0, 200)));
await p.goto("http://localhost:3001/introduction", { waitUntil: "networkidle" });
await p.waitForSelector(".react-flow__node-step");
const zoom = () => p.evaluate(() => getComputedStyle(document.querySelector(".react-flow__viewport")).transform);
const before = await zoom();
await p.getByRole("button", { name: "Full screen" }).click();
await p.waitForTimeout(800);
const fsTag = await p.evaluate(() => document.fullscreenElement?.className);
const box = await p.evaluate(() => { const r = document.fullscreenElement?.getBoundingClientRect(); return r && [r.width, r.height]; });
const during = await zoom();
await p.screenshot({ path: "fs.png" });
await p.mouse.move(800, 500); await p.mouse.wheel(0, -300); await p.waitForTimeout(300);
const wheeled = await zoom();
await p.getByRole("button", { name: "Exit full screen" }).click();
await p.waitForTimeout(800);
console.log({ before, fsTag, box, during, wheeled, after: await zoom(), exited: await p.evaluate(() => document.fullscreenElement === null), errs });
await b.close();
EOF
sleep 6; node fs.mjs

